    assert.equal(rmStatSafe(manager.catalogCachePath), before, "相同摘要不再落盘");
    await manager.recordCatalogTools("srv", new Map([["t1", { description: "   " }]]));
    assert.equal(manager.catalogCache.get("srv").summary, "desc-b", "全空白摘要短路不覆盖");
