    // catalogServersFor：全局 + 项目聚合，禁用过滤，同名项目级被顶掉。
    manager.projectStore.data.servers.push(normalizeServer({ ...quietServer("psrv2", { enabled: false }) }));
    const catalog = await manager.catalogServersFor(proj);
