    assert.equal(catalog.get("psrv").scope, "project");
    // 空 cwd 只出全局。
    const onlyGlobal = await manager.catalogServersFor("");
    assert.deepEqual([...onlyGlobal.keys()], ["glob"]);

    // projectStoreFor 缓存命中复用。
